export const CHARACTER_BY_ID: Map<string, CharacterDef> = new Map(CHARACTERS.map((c) => [c.id, c]));

export function getCharacter(id: string): CharacterDef {
    const character = CHARACTER_BY_ID.get(id);
    if (!character) {
        throw new Error("Unknown character " + id);
    }
    return character;
}

// "Beat Barrows", "Kill Count Draynor in Lumbridge"
export function describeUnlockTask(task: UnlockTask): string {
    const map = getMap(task.mapId).name;
    switch (task.kind) {
        case "beatMap":
            return `Beat ${map}`;
        case "killBoss":
            return `Kill ${getEnemy(task.enemyId).name} in ${map}`;
        case "survive":
            return `Survive ${Math.round(task.seconds / 60)} minutes in ${map}`;
    }
}
