// The melee bosses' gap closer: a red circle on the spot you're standing on,
// then the boss jumps onto it (the Barrows brothers and Count Draynor)
function leapAttack(damage: number, radius: number, cooldown: number): BossAttackDef {
    return {
        name: "Leap",
        kind: "blast",
        damage,
        windup: 1,
        cooldown,
        range: 10,
        minRange: 3.5,
        radius,
        weight: 2,
        leap: true,
        // Arms up, the god spell cast, for the jump
        seq: 811,
        sound: 2500,
    };
}

