export const ENEMY_BY_ID: Map<string, EnemyDef> = new Map(ENEMIES.map((e) => [e.id, e]));

export function getEnemy(id: string): EnemyDef {
    const enemy = ENEMY_BY_ID.get(id);
    if (!enemy) {
        throw new Error("Unknown enemy " + id);
    }
    return enemy;
}
