const GODSWORD_SOUND = 2500;

// Every godsword swings the same; the hilt sets its special attack
function godsword(
    id: string,
    name: string,
    objId: number,
    description: string,
    special: SpecialAttackDef,
): WeaponDef {
    return {
        id,
        name,
        kind: "sweep",
        description: `A heavy two-handed sweep. ${description}`,
        iconObjId: objId,
        playerSeq: GODSWORD_SEQ,
        sound: GODSWORD_SOUND,
        hitSound: -1,
        rarity: "rare",
        style: "melee",
        family: "godsword",
        special,
        levels: levels(
            {
                damage: 20,
                cooldown: 1.9,
                amount: 1,
                area: 2.8,
                arc: 0.95,
                pierce: 0,
                speed: 0,
                duration: 0,
                knockback: 1,
                objId,
            },
            { damage: 24, description: "+4 damage." },
            { area: 3.1, description: "+11% reach." },
            { cooldown: 1.7, description: "Swings a little faster." },
            { damage: 30, description: "+6 damage." },
        ),
    };
}

